function binarySearchImpl(sortedArr, target) {
  let left = 0, right = sortedArr.length - 1;
  while (left <= right) {
    const mid = Math.floor((left + right) / 2);
    if (sortedArr[mid] === target) return mid;
    sortedArr[mid] < target ? left = mid + 1 : right = mid - 1;
  }
  return -1;
}

function empiricalComplexityCheck(fn, sizes) {
  return sizes.map(size => {
    const arr = Array.from({length: size}, () => Math.floor(Math.random() * size * 2));
    const t0 = Date.now();
    fn(arr);
    return { size, timeMs: Date.now() - t0 };
  });
}

