function factorialTraced(n, depth = 0) {
  const indent = '  '.repeat(depth);
  console.log(`${indent}PUSH factorial(${n})`);
  if (n <= 1) {
    console.log(`${indent}POP factorial(${n}) -> 1 [base case]`);
    return 1;
  }
  const result = n * factorialTraced(n - 1, depth + 1);
  console.log(`${indent}POP factorial(${n}) -> ${result}`);
  return result;
}

function fibonacciRecursive(n) {
  if (n <= 1) return n;
  return fibonacciRecursive(n - 1) + fibonacciRecursive(n - 2);
}

function countFibonacciCalls(n) {
  let calls = 0;
  function helper(n) {
    calls++;
    if (n <= 1) return n;
    return helper(n - 1) + helper(n - 2);
  }
  helper(n);
  return calls;
}

