// STEP 1: CLARIFY
// Q: Can the same problemId be attempted multiple times? -> Yes, track all confidence scores
// Q: What confidence values are valid? -> 'struggled', 'solid', 'easy'
// STEP 2: EXAMPLES
// addAttempt('p1','hash_map','easy') then getPatternStats('hash_map') -> {totalAttempts:1, averageConfidenceScore:3}

class PracticeTracker {
  constructor() {
    this.attempts = new Map();
    this.confidenceMap = { struggled: 1, solid: 2, easy: 3 };
  }
  addAttempt(problemId, pattern, confidence) {
    if (!this.attempts.has(problemId)) {
      this.attempts.set(problemId, { pattern, confidenceScores: [] });
    }
    this.attempts.get(problemId).confidenceScores.push(this.confidenceMap[confidence]);
  }
  getPatternStats(pattern) {
    let totalAttempts = 0;
    let sumConfidence = 0;
    for (const record of this.attempts.values()) {
      if (record.pattern === pattern) {
        totalAttempts += record.confidenceScores.length;
        sumConfidence += record.confidenceScores.reduce((a,b) => a+b, 0);
      }
    }
    return {
      totalAttempts,
      averageConfidenceScore: totalAttempts > 0 ? sumConfidence / totalAttempts : 0
    };
  }
  countAttemptsRecursive(problemIds) {
    if (problemIds.length === 0) return 0;
    const [first, ...rest] = problemIds;
    const found = this.attempts.has(first) ? 1 : 0;
    return found + this.countAttemptsRecursive(rest);
  }
  getWeakestPattern() {
    const patternTotals = new Map();
    for (const record of this.attempts.values()) {
      if (!patternTotals.has(record.pattern)) {
        patternTotals.set(record.pattern, { sum: 0, count: 0 });
      }
      const entry = patternTotals.get(record.pattern);
      entry.sum += record.confidenceScores.reduce((a,b) => a+b, 0);
      entry.count += record.confidenceScores.length;
    }
    let weakest = null, weakestAvg = Infinity;
    for (const [pattern, { sum, count }] of patternTotals.entries()) {
      const avg = sum / count;
      if (avg < weakestAvg) { weakestAvg = avg; weakest = pattern; }
    }
    return weakest;
  }
}
